def migrate_files_to_single_bucket(apps, schema_editor):
    FileReference = apps.get_model('file_transfer', 'FileReference')
    CradleUser = apps.get_model('user', 'CradleUser')

    # Cast to list immediately to avoid cursor issues during deletion
    files_to_migrate = list(FileReference.objects.filter(bucket_name__isnull=False).exclude(bucket_name=''))
    if not files_to_migrate:
        return

    from botocore.exceptions import ClientError
    from file_transfer.s3_utils import ensure_bucket_exists
    from file_transfer.storage import FileTransferStorage

    target_bucket = FileTransferStorage.bucket_name
    ensure_bucket_exists(target_bucket)
    client = FileTransferStorage().connection.meta.client

    def object_exists(bucket, key):
        try:
            client.head_object(Bucket=bucket, Key=key)
            return True
        except ClientError:
            return False

    failures = []
    for file_ref in files_to_migrate:
        try:
            with transaction.atomic():
                old_id = file_ref.id
                new_id = "-".join(file_ref.minio_file_name.split("-")[:5])
                
                if not new_id or FileReference.objects.filter(id=new_id).exists():
                    print(f"Skipping {file_ref.id}: New ID '{new_id}' is invalid or already exists.")
                    continue

                user = None
                try:
                    user = CradleUser.objects.get(id=file_ref.bucket_name)
                except CradleUser.DoesNotExist:
                    pass

                new_file_path = f"{new_id}-{file_ref.file_name}"
                if file_ref.minio_file_name and object_exists(file_ref.bucket_name, file_ref.minio_file_name):
                    client.copy_object(
                        Bucket=target_bucket,
                        Key=new_file_path,
                        CopySource={"Bucket": file_ref.bucket_name, "Key": file_ref.minio_file_name},
                    )
                else:
                    print(f"File missing in MinIO for {file_ref.id}, skipping DB record swap.")
                    continue

                data = model_to_dict(file_ref, exclude=['id', 'file', 'user', 'note', 'digest'])
                
                data['user_id'] = user.id if user else file_ref.user_id
                data['note_id'] = file_ref.note_id
                data['digest_id'] = file_ref.digest_id
                
                data['id'] = new_id
                data['file'] = new_file_path
                data['bucket_name'] = ""

                file_ref.delete()
                FileReference.objects.bulk_create([FileReference(**data)])

                print(f"Success: Migrated {old_id} -> {new_id}")

        except Exception as e:
            msg = f"Error migrating file {file_ref.id}: {str(e)}"
            print(msg)
            failures.append(msg)

    if failures:
        raise Exception("There were issues with the file migration")

def reverse_migration(apps, schema_editor):
    """
    Reverse migration is not fully supported as it would require
    moving files back to user buckets which may not exist.
    This just clears the file field.
    """
    FileReference = apps.get_model('file_transfer', 'FileReference')
    FileReference.objects.update(file='', user=None)


